import {motionExamples,motionExampleUrl} from './motion-examples.js';
import {demoTargets} from './demo-targets.js';
import {mountSearchSuggestions} from './sky-search.js';
import {MILKY_WAY_COLOURS} from './sky-palette.js';
import {isCellView,cellMarkup,mountCell} from './cell-view.js';
import {ORDER,CELL_ARCMIN,CELL_COUNT,cellAt,center,boundary,nearby,visibleCells,gridOrder,MIRA_CELL,parseSky,channelTransportHz} from './sky-model.js';
export function skyMarkup(){if(isCellView())return cellMarkup();return `<main id="main" class="explorer" data-sky><section class="map-area sky-area" aria-label="SPHEREx sky map"><div id="aladin-sky" aria-label="Interactive SPHEREx sky image"></div><div class="sky-loading" id="sky-loading" role="status">Loading SPHEREx…</div><div class="sky-bottom"><output id="sky-coordinates">RA 266.4000° · Dec −29.0000°</output><div class="sky-zoom"><button data-sky-action="out" aria-label="Zoom out">−</button><button data-sky-action="in" aria-label="Zoom in">+</button></div></div></section><aside class="rail sky-rail"><label class="sky-wavelength sky-test-regions">Test regions<select id="sky-test-region" aria-label="Test regions"><option value="">Choose a region…</option>${demoTargets.map((t,i)=>`<option value="${i}">${t.name}</option>`).join('')}<optgroup label="Motion demos">${motionExamples.filter(e=>e.id!=='barnard').map(e=>`<option value="motion:${e.id}">${e.name}</option>`).join('')}</optgroup></select></label><div id="sky-selection"></div><div class="sky-search-bar"><form id="sky-object-form" role="search"><div class="sky-object-field"><label for="sky-object-query">Search objects</label><input id="sky-object-query" name="object" type="search" placeholder="Name or catalogue ID" aria-label="Search known objects" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="sky-object-suggestions" maxlength="120" required disabled><div id="sky-object-suggestions" role="listbox" aria-label="Object suggestions" hidden></div></div><button type="submit" id="sky-object-submit" disabled>Go</button></form><div class="sky-search-result" id="sky-object-result" role="status" hidden></div></div><section class="sky-coordinate-search" aria-label="Go to coordinates"><h2>Go to coordinates</h2><form id="sky-coordinate-form"><div class="coord-inputs"><label>RA °<input name="ra" aria-label="Right ascension" type="number" step="any" min="0" max="359.999999" required placeholder="225.5413"></label><label>Dec °<input name="dec" aria-label="Declination" type="number" step="any" min="-90" max="90" required placeholder="59.5225"></label><button aria-label="Go to coordinates">→</button></div></form></section><label class="sky-wavelength">Wavelength<select id="sky-wave" aria-label="Wavelength" disabled><option>Loading…</option></select></label></aside></main>`;}
export async function mountSky(){
 if(isCellView())return mountCell();
 const root=document.querySelector('[data-sky]');if(!root)return()=>{};
 let dead=false,viewer,survey,overlay,selected=parseSky(location.search),timer,gridTimer,channel=62,metadata,drawOrder=2,milkyWay=true,paletteReady=false,searchController,searchToken=0,objectMarker,suggestions;
 const q=s=>root.querySelector(s),loading=q('#sky-loading'),panel=q('#sky-selection');
 const selectionEvents=new AbortController();
 const clean=()=>{selectionEvents.abort();dead=true;clearTimeout(timer);clearTimeout(gridTimer);searchController?.abort();suggestions?.destroy();};
 const coordText=p=>`RA ${p.ra.toFixed(4)}° · Dec ${p.dec<0?'−':'+'}${Math.abs(p.dec).toFixed(4)}°`;
 function url(){const u=new URL(location.href);u.search='';if(selected){u.searchParams.set('hpx',selected.id);u.searchParams.set('order',selected.order);}u.searchParams.set('channel',channel);history.replaceState({},'',u.pathname+u.search);}
 function coordinates(){if(dead||!viewer)return;const p=selected?center(selected.id,selected.order):(()=>{const [ra,dec]=viewer.getRaDec();return {ra,dec};})();q('#sky-coordinates').textContent=coordText(p);for(const [name,value] of [['ra',p.ra],['dec',p.dec]]){const input=q(`[name="${name}"]`);if(document.activeElement!==input)input.value=value.toFixed(4);}}
 function updatePanel(){if(dead)return;if(!selected){panel.innerHTML=`<h1>Choose a patch.</h1><button class="button full-width" data-sky-action="find">Find a cell for me →</button>`;return;}
 const isCell=selected.order===ORDER,isMira=isCell&&selected.id===MIRA_CELL;
 panel.innerHTML=`<button class="back-button" data-sky-action="whole">← Whole sky</button><h1>${isCell?'Cell '+selected.id:'Region '+selected.id}</h1>${isCell?`<a class="button full-width" href="/explore/?hpx=${selected.id}&order=9&channel=${channel}&view=cell">Open region fully ↗</a>${isMira?`<div class="cell-preview"><img src="/assets/mira-1.png" alt="November observation"><img src="/assets/mira-2.png" alt="June observation"></div><p class="tiny">Example observations · November 2025 and June 2026</p><a href="/assets/mira.json" download="sate-spherex-observation.json" class="button outline full-width">Download source records ↓</a>`:''}<div class="rail-actions"><button class="button outline" data-sky-action="focus">Centre this cell</button><button class="button outline" data-sky-action="find">Find another cell →</button></div><div class="sky-neighbours"><span>Neighbouring cells</span><div>${nearby(selected.id).filter(id=>id!==selected.id).map(id=>`<button data-neighbour="${id}" aria-label="Select neighbouring cell ${id}">${id}</button>`).join('')}</div></div><button class="share-button" data-sky-action="copy">Copy cell link</button>`:`<p class="rail-intro">${(4**(ORDER-selected.order)).toLocaleString()} search cells in this region.</p><button class="button full-width" data-sky-action="open">Open region ↗</button>`}`;
 }
 function clearSelection(){selected=null;updatePanel();coordinates();draw();url();}
 function pick(id,order,{focus=false}={}){selected={id,order};if(viewer&&focus){const p=center(id,order);viewer.gotoRaDec(p.ra,p.dec);viewer.setFoV(order===ORDER?.48:Math.min(150,Math.max(.48,CELL_ARCMIN/60*2**(ORDER-order)*1.4)));}updatePanel();coordinates();draw();url();}
 function draw(){if(dead||!viewer||!overlay)return;clearTimeout(gridTimer);gridTimer=setTimeout(()=>{if(dead)return;const [ra,dec]=viewer.getRaDec(),fov=viewer.getFov()[0];drawOrder=gridOrder(fov);let ids=visibleCells(ra,dec,fov,drawOrder);if(ids.length>350)ids=ids.slice(0,350);const shapes=ids.map(id=>A.polygon(boundary(id,drawOrder,drawOrder<3?8:2),{color:'#aab5c11f',lineWidth:0.45,hoverColor:'#aabcc43d',selectionColor:'#b6c8cf52',selectionLineWidth:.8}));if(selected){if(selected.order===ORDER&&fov<4)for(const id of nearby(selected.id))if(id!==selected.id)shapes.push(A.polygon(boundary(id),{color:'#b4c0cb29',lineWidth:.55,hoverColor:'#b4c0cb3d',selectionColor:'#b4c0cb52',selectionLineWidth:.8}));shapes.push(A.polygon(boundary(selected.id,selected.order),{color:'#b9c8d68c',lineWidth:1.1,hoverColor:'#b9c8d699',selectionColor:'#b9c8d699',selectionLineWidth:1.1}));}overlay.removeAll();overlay.addFootprints(shapes);},80);}
 let A;
 updatePanel();
 try{
  const result=await Promise.all([import('./vendor/aladin-3.8.1.js'),fetch('/assets/spherex-survey.json').then(r=>{if(!r.ok)throw Error('Metadata unavailable');return r.json();})]);if(dead)return clean;A=result[0].default;metadata=result[1];await A.init;if(dead)return clean;
  const requested=Number(new URLSearchParams(location.search).get('channel'));if(new URLSearchParams(location.search).has('channel')&&Number.isInteger(requested)&&requested>=0&&requested<102&&!metadata.blankFrames.includes(requested))channel=requested;
  q('#sky-wave').innerHTML=metadata.wavelengths.map((w,i)=>`<option value="${i}" ${i===channel?'selected':''} ${metadata.blankFrames.includes(i)?'disabled':''}>${w.toFixed(3)} µm${metadata.blankFrames.includes(i)?' — no data':''}</option>`).join('');q('#sky-wave').disabled=false;updatePanel();
  survey=A.imageHiPS(metadata.url,{imgFormat:'png',successCallback:h=>{if(dead)return;survey=h;h.setFrequency({unit:'Hz',value:channelTransportHz(channel)});if(paletteReady)h.setColormap(milkyWay?'sate-milky-way':'native');loading.hidden=true;},errorCallback:()=>{loading.hidden=false;loading.textContent='SPHEREx imagery unavailable. Reload to retry.';}});
  const initial=selected?center(selected.id,selected.order):{ra:266.4,dec:-29};
  viewer=A.aladin('#aladin-sky',{survey,target:`${initial.ra} ${initial.dec}`,fov:selected?Math.min(360,Math.max(.48,CELL_ARCMIN/60*2**(ORDER-selected.order)*1.4)):360,projection:'AIT',cooFrame:'ICRSd',showZoomControl:false,showLayersControl:false,showFullscreenControl:false,showFrame:false,showProjectionControl:false,showStatusBar:false,showGotoControl:false,showReticle:false,showCooGrid:false,showFov:false,showCooLocation:false,log:false,inertia:false,backgroundColor:'#000000'});
  // Aladin's background option colours unfilled sky inside the projection.
  // Its WebGL clear colour is separately initialized to grey (0.1): set this
  // viewer's existing context to black for the area outside the sky oval.
  const imageCanvas=q('.aladin-imageCanvas');
  const blackBackdrop=()=>{if(dead)return;imageCanvas?.getContext('webgl2')?.clearColor(0,0,0,1);viewer.setBackgroundColor('#000000');};
  blackBackdrop();imageCanvas?.addEventListener('webglcontextrestored',blackBackdrop,{signal:selectionEvents.signal});
  // Aladin 3.8.1 destructures an absent inverse-projection result outside the
  // sky ellipse. Normalize that TypeError across browser engines; their error
  // messages differ. Return the absent coordinate its own event handlers expect.
  const projectPixel=viewer.pix2world.bind(viewer);viewer.pix2world=(...args)=>{try{return projectPixel(...args);}catch(error){if(error instanceof TypeError)return undefined;throw error;}};
  viewer.addColormap('sate-milky-way',MILKY_WAY_COLOURS);paletteReady=true;survey.setColormap('sate-milky-way');
  q('#sky-object-query').disabled=false;q('#sky-object-submit').disabled=false;objectMarker=A.catalog({name:'Search result',shape:'circle',sourceSize:18,color:'#98c3ed',displayLabel:true,labelColumn:'name',labelColor:'#dae4ef',labelFont:'12px Public Sans, Arial, sans-serif'});viewer.addCatalog(objectMarker);
  overlay=A.graphicOverlay({color:'#9ba7b3',lineWidth:1});viewer.addOverlay(overlay);
  viewer.on('click',p=>{if(!p.isDragging&&Number.isFinite(p.ra)&&Number.isFinite(p.dec))pick(cellAt(p.ra,p.dec,drawOrder),drawOrder);});
  // Aladin emits its click callback only inside the projection. Listen for a
  // stationary pointer release on the canvas to handle the surrounding blank area.
  const sky=q('#aladin-sky'),events={capture:true,signal:selectionEvents.signal};let press=null;
  sky.addEventListener('pointerdown',e=>{press=e.isPrimary&&e.button===0&&e.target instanceof HTMLCanvasElement?{id:e.pointerId,x:e.clientX,y:e.clientY,moved:false}:null;},events);
  sky.addEventListener('pointermove',e=>{if(press?.id===e.pointerId&&Math.hypot(e.clientX-press.x,e.clientY-press.y)>6)press.moved=true;},events);
  sky.addEventListener('pointercancel',()=>{press=null;},events);
  sky.addEventListener('pointerup',e=>{const start=press;press=null;if(!start||start.id!==e.pointerId||start.moved||Math.hypot(e.clientX-start.x,e.clientY-start.y)>6)return;const r=sky.getBoundingClientRect(),position=viewer.pix2world(e.clientX-r.left,e.clientY-r.top,'icrs');if(!position||!position.every(Number.isFinite))clearSelection();},events);
  viewer.on('positionChanged',()=>{coordinates();draw();});viewer.on('zoomChanged',()=>{coordinates();draw();});
  viewer.on('resizeChanged',draw);draw();coordinates();
  timer=setTimeout(()=>{if(!dead&&!loading.hidden)loading.textContent='SPHEREx is taking longer to load. You can still select a region.';},20000);
 }catch(e){if(!dead){loading.hidden=false;loading.textContent='The sky viewer could not load. Please reload in a WebGL2 browser.';}return clean;}
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!viewer)return;if(b.dataset.neighbour){pick(Number(b.dataset.neighbour),ORDER,{focus:true});return;}switch(b.dataset.skyAction){
 case'palette':milkyWay=!milkyWay;survey.setColormap(milkyWay?'sate-milky-way':'native');b.textContent=milkyWay?'Milky Way':'Grayscale';b.setAttribute('aria-pressed',String(milkyWay));break;
 case'whole':selected=null;viewer.gotoRaDec(266.4,-29);viewer.setFoV(360);updatePanel();coordinates();draw();url();break;
 case'in':viewer.setFoV(Math.max(.08,viewer.getFov()[0]/2));break;
 case'out':viewer.setFoV(Math.min(360,viewer.getFov()[0]*2));break;
 case'open':case'focus':if(selected)pick(selected.id,selected.order,{focus:true});break;
 case'find':{const id=selected?.order===ORDER?(selected.id+1)%CELL_COUNT:MIRA_CELL+1;pick(id,ORDER,{focus:true});break;}
 case'copy':try{await navigator.clipboard.writeText(location.href);b.textContent='Link copied';}catch{b.textContent='Copy this page’s URL';}break;
 }});
 suggestions=mountSearchSuggestions(q('#sky-object-form'));
 q('#sky-object-form').addEventListener('submit',async e=>{e.preventDefault();const name=q('#sky-object-query').value.trim();if(!name)return;suggestions.close();searchController?.abort();searchController=new AbortController();const token=++searchToken,result=q('#sky-object-result'),button=q('#sky-object-submit');result.hidden=false;result.textContent='Searching…';result.removeAttribute('data-error');button.textContent='…';q('#sky-object-form').setAttribute('aria-busy','true');
  try{const r=await fetch('/api/object-search?'+new URLSearchParams({q:name}),{signal:searchController.signal}),object=await r.json();if(!r.ok)throw Error(object.error||'Object search unavailable.');if(dead||token!==searchToken)return;if(!Number.isFinite(object.ra)||!Number.isFinite(object.dec))throw Error('No valid position returned.');pick(cellAt(object.ra,object.dec),ORDER);viewer.gotoRaDec(object.ra,object.dec);viewer.setFoV(.48);objectMarker.removeAll();objectMarker.addSources([A.source(object.ra,object.dec,{name:object.name})]);suggestions.remember(name);result.textContent=object.name+' · '+(object.epoch===2026?'2026 position':'catalogue position');result.title=object.epoch===2026?'CDS Sesame · approximate 2026 position from catalogue proper motion.':'CDS Sesame · J2000 catalogue position.';q('#sky-coordinates').textContent=coordText(object);draw();
  }catch(error){if(dead||token!==searchToken||error.name==='AbortError')return;result.textContent=error.message;result.dataset.error='true';}finally{if(!dead&&token===searchToken){button.textContent='Go';q('#sky-object-form').setAttribute('aria-busy','false');}}
 });
 q('#sky-coordinate-form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const f=new FormData(e.target),ra=Number(f.get('ra')),dec=Number(f.get('dec'));if(Number.isFinite(ra)&&Number.isFinite(dec)&&ra>=0&&ra<360&&dec>=-90&&dec<=90)pick(cellAt(ra,dec),ORDER,{focus:true});});
 q('#sky-test-region').addEventListener('change',e=>{if(e.target.value==='')return;if(e.target.value.startsWith('motion:')){location.href=motionExampleUrl(e.target.value.slice(7));return;}const target=demoTargets[Number(e.target.value)];if(!target||!viewer||!metadata)return;channel=metadata.wavelengths.reduce((best,w,i)=>!metadata.blankFrames.includes(i)&&Math.abs(w-target.wave)<Math.abs(metadata.wavelengths[best]-target.wave)?i:best,0);q('#sky-wave').value=String(channel);survey.setFrequency({unit:'Hz',value:channelTransportHz(channel)});pick(cellAt(target.ra,target.dec),ORDER,{focus:true});objectMarker.removeAll();objectMarker.addSources([A.source(target.ra,target.dec,{name:target.name})]);});
 q('#sky-wave').addEventListener('change',e=>{channel=Number(e.target.value);survey.setFrequency({unit:'Hz',value:channelTransportHz(channel)});updatePanel();url();});
 return clean;
}
